import {ITEMS,addItem,countItem,removeItem} from './inventory.js';
export function orderErrand({p,slots,show,close,sync,sound,reward,shop,changed,stored=()=>[],bags=()=>[]}){
 const available=()=>p.rewards.includes('c3-arrival'),ready=()=>p.orderErrand==='collect'&&countItem(slots,'order_parcel')>=3;
 function talk(name){if(!available()||p.orderErrand==='done')return false;if(p.orderErrand==='collect'){const owned=countItem(slots,'order_parcel')+countItem(stored(),'order_parcel')+bags().reduce((n,b)=>n+countItem(b.items||[],'order_parcel'),0);let marked=p.orderParcelMask||0;while(marked.toString(2).replaceAll('0','').length>owned){for(let i=2;i>=0;i--)if(marked&(1<<i)){marked&=~(1<<i);break}}if(marked!==p.orderParcelMask){p.orderParcelMask=marked;changed()}}const choices=[];
  if(p.orderErrand==='idle')choices.push(['Собрать три свёртка',()=>{p.orderErrand='collect';p.orderParcelMask=0;changed();sound();show(name,'Мне нужны три свёртка: у южного склада, возле мишеней и за гостевым домом. Всё внутри стен. Вернись с ними — дам плотный дорожный плащ. Хоть что-то в этой крепости должно защищать от дождя без приказа коменданта.')}]);
  if(ready())choices.push(['Отдать три свёртка',()=>{const copy=slots.map(i=>i?{...i}:null),id='cloak_travel_'+p.classId;if(!removeItem(copy,'order_parcel',3))return;if(!countItem(slots,id)&&!addItem(copy,id))return show(name,'Освободи место для плаща. Свёртки пока оставь у себя.');slots.splice(0,slots.length,...copy);p.orderErrand='done';reward(p,'order-errand','quest',150);changed();sound();show(name,'Все три! Прекрасно. Два дня искал человека, который умеет читать накладную и не спорит со словом «три». Плащ твой. Ячейка для него слева в инвентаре.')}]);
  choices.push(['Посмотреть припасы',()=>shop('order_supplies')],['До встречи',close]);
  show(name,p.orderErrand==='idle'?'Хочешь заработать без драки? Помоги собрать поставку. Три свёртка развезли по всему двору, а мне предлагают самому побегать. С моей-то ногой. Нога, между прочим, совершенно здорова — просто я интендант.':ready()?'Вижу все свёртки. Давай сюда, пока кто-нибудь опять не решил их «временно переложить».':'Свёртки ещё во дворе. Южный склад, мишени и место за гостевым домом. На карте я их отметил.',choices);return true;
 }
 function take(index){if(p.orderErrand!=='collect'||p.orderParcelMask&(1<<index))return false;if(!addItem(slots,'order_parcel')){show('Свёрток','Освободи место в сумке.');return true}p.orderParcelMask|=1<<index;changed();sound();return true}
 return {talk,take,objective:()=>p.orderErrand==='collect'?'Поставка для Бертольда: '+(ready()?'вернитесь к интенданту':`соберите свёртки во дворе (${countItem(slots,'order_parcel')} / 3)`):'',marker:id=>id==='c3-quartermaster'&&available()&&p.orderErrand!=='done'?{symbol:ready()?'?':'!',optional:true}:null};
}
